<canvas id="canvas"></canvas><div class="hud">PATCH <b id="h-mode">KITES</b><br>RINGS <b id="h-rings">7</b><br>ROTATE <b id="h-rot">0</b><br><span class="sub">TILES</span> <b id="h-tiles">0</b></div><?php $interactionHints=[['type'=>'drag','label'=>'rotate'],['type'=>'click','label'=>'shift']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-mode="kites">KITES</button><button class="control-btn" data-mode="stars">STARS</button><button class="control-btn" data-mode="web">WEB</button></div></div><div><div class="slider-row"><span class="slider-label">RINGS</span><input type="range" id="sl-rings" min="3" max="11" value="7"><span class="slider-value" id="sv-rings">7</span></div></div><div><div class="slider-row"><span class="slider-label">SCALE</span><input type="range" id="sl-scale" min="55" max="145" value="92"><span class="slider-value" id="sv-scale">0.92</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-spin">SPIN</button><button class="control-btn" id="btn-phase">PHASE</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='kites',rings=7,scale=.92,rot=0,spin=true,phase=0;var hr=document.getElementById('h-rings'),ho=document.getElementById('h-rot'),ht=document.getElementById('h-tiles'),hm=document.getElementById('h-mode'),sr=document.getElementById('sl-rings'),ss=document.getElementById('sl-scale'),vr=document.getElementById('sv-rings'),vs=document.getElementById('sv-scale');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function tile(cx,cy,r,a,i){var pts=[],thin=mode==='web'?.42:.62;for(var k=0;k<4;k++){var rr=k%2?r:r*thin,aa=a+k*Math.PI/2+phase;pts.push([cx+Math.cos(aa)*rr,cy+Math.sin(aa)*rr])}x.beginPath();x.moveTo(pts[0][0],pts[0][1]);for(var q=1;q<pts.length;q++)x.lineTo(pts[q][0],pts[q][1]);x.closePath();x.fillStyle=i%2?'rgba(0,245,212,.11)':'rgba(123,44,191,.13)';x.strokeStyle=i%2?'rgba(0,245,212,.46)':'rgba(123,44,191,.48)';x.fill();x.stroke()}function draw(){if(spin)rot+=.003;x.fillStyle='rgba(10,10,15,.2)';x.fillRect(0,0,W,H);x.globalCompositeOperation='lighter';var cx=W/2,cy=H/2,base=Math.min(W,H)*.055*scale,count=0;for(var r=1;r<=rings;r++){var n=r*10,rad=base*r*1.35;for(var i=0;i<n;i++){var a=i/n*Math.PI*2+rot+r*.21,tw=base*(mode==='stars'?(1+.25*Math.sin(i)):1);tile(cx+Math.cos(a)*rad,cy+Math.sin(a)*rad,tw,a+Math.PI/5*r,count++);}}x.globalCompositeOperation='source-over';hm.textContent=mode.toUpperCase();hr.textContent=rings;vr.textContent=rings;ho.textContent=Math.round(rot*180/Math.PI)%360;ht.textContent=count;vs.textContent=scale.toFixed(2);requestAnimationFrame(draw)}c.onpointerdown=e=>{phase+=.13;if(typeof SFX!=='undefined')SFX.play('ripple',100)};c.onpointermove=e=>{if(e.buttons){rot+=(e.movementX||0)*.006;if(typeof SFX!=='undefined')SFX.play('move',120)}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(q=>q.classList.toggle('active',q===b));if(typeof SFX!=='undefined')SFX.play('toggle')});sr.oninput=()=>rings=+sr.value;ss.oninput=()=>scale=+ss.value/100;document.getElementById('btn-spin').onclick=e=>{spin=!spin;e.currentTarget.classList.toggle('active',spin);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-phase').onclick=()=>{phase+=Math.PI/10;if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>